/// The Python reader's exception classes, one variant each (see the table above).
#[derive(Debug)]
pub enum Error {
    UnknownName(String),
    Invalid(String),
    TreeRead(String),
    Layout(String),
    Io(String, io::Error),
}

impl Error {
    /// A short name for the kind: unknown, value, tree, layout or os.
    pub fn kind(&self) -> &'static str {
        match self {
            Error::UnknownName(_) => "unknown",
            Error::Invalid(_) => "value",
            Error::TreeRead(_) => "tree",
            Error::Layout(_) => "layout",
            Error::Io(..) => "os",
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::UnknownName(n) => write!(f, "unknown name: {n} (names take a scope: repo., workspace. or machine.)"),
            Error::Invalid(m) | Error::TreeRead(m) | Error::Layout(m) => f.write_str(m),
            Error::Io(m, e) => write!(f, "{m}: {e}"),
        }
    }
}

impl std::error::Error for Error {}

pub type Result<T> = std::result::Result<T, Error>;

fn io_err(path: &str, e: io::Error) -> Error {
    Error::Io(path.to_string(), e)
}

// --- Path spelling (pathlib and posixpath, ported) ---

/// `str(Path(s))`: empty and `.` parts dropped, a trailing slash dropped, exactly
/// two leading slashes kept (POSIX leaves `//` implementation-defined), `..` kept.
pub(crate) fn pl(s: &str) -> String {
    let lead = if s.starts_with("//") && !s.starts_with("///") {
        "//"
    } else if s.starts_with('/') {
        "/"
    } else {
        ""
    };
    let body: Vec<&str> = s.split('/').filter(|p| !p.is_empty() && *p != ".").collect();
    if lead.is_empty() && body.is_empty() {
        return ".".to_string();
    }
    format!("{lead}{}", body.join("/"))
}

/// `Path(a) / b`, both as pathlib spells them.
pub(crate) fn join(a: &str, b: &str) -> String {
    if b.starts_with('/') {
        pl(b)
    } else if a.ends_with('/') {
        pl(&format!("{a}{b}"))
    } else {
        pl(&format!("{a}/{b}"))
    }
}

/// `Path(p).parent` for a pathlib-spelled `p`.
pub(crate) fn parent(p: &str) -> String {
    match p.rfind('/') {
        None => ".".to_string(),
        Some(i) => {
            let head = &p[..i];
            if head.is_empty() || head == "/" { p[..=i].to_string() } else { head.to_string() }
        }
    }
}

/// `os.path.normpath`.
pub(crate) fn normpath(path: &str) -> String {
    if path.is_empty() {
        return ".".to_string();
    }
    let initial = if path.starts_with("//") && !path.starts_with("///") {
        2
    } else if path.starts_with('/') {
        1
    } else {
        0
    };
    let mut comps: Vec<&str> = Vec::new();
    for comp in path.split('/') {
        if comp.is_empty() || comp == "." {
            continue;
        }
        if comp != ".." || (initial == 0 && comps.is_empty()) || comps.last() == Some(&"..") {
            comps.push(comp);
        } else if !comps.is_empty() {
            comps.pop();
        }
    }
    let out = format!("{}{}", "/".repeat(initial), comps.join("/"));
    if out.is_empty() { ".".to_string() } else { out }
}

/// `_norm`: normpath, with a leading `//` collapsed to `/` as the shell reader does.
fn norm(path: &str) -> String {
    let p = normpath(path);
    if p.starts_with("//") { format!("/{}", p.trim_start_matches('/')) } else { p }
}

fn cwd() -> Result<String> {
    let dir = std::env::current_dir().map_err(|e| io_err(".", e))?;
    utf8(dir.into_os_string(), "the current folder")
}

/// `os.path.abspath`.
pub(crate) fn abspath(p: &str) -> Result<String> {
    if p.starts_with('/') { Ok(normpath(p)) } else { Ok(normpath(&format!("{}/{p}", cwd()?))) }
}

/// `os.path.realpath(p)` (non-strict): symlinks resolved, a missing tail kept as
/// named, a loop left unresolved; any error on the way reads as "not a link".
pub(crate) fn realpath(filename: &str) -> Result<String> {
    // None marks a resolved symlink: the link path is the entry after it.
    let mut rest: Vec<Option<String>> = filename.split('/').rev().map(|s| Some(s.to_string())).collect();
    let mut part_count = rest.len();
    let mut path = if filename.starts_with('/') { "/".to_string() } else { cwd()? };
    let mut seen: HashMap<String, Option<String>> = HashMap::new();
    while part_count > 0 {
        let name = match rest.pop() {
            Some(Some(n)) => n,
            Some(None) => {
                if let Some(Some(link)) = rest.pop() {
                    seen.insert(link, Some(path.clone()));
                }
                continue;
            }
            None => break,
        };
        part_count -= 1;
        if name.is_empty() || name == "." {
            continue;
        }
        if name == ".." {
            path = match path.rfind('/') {
                Some(0) | None => "/".to_string(),
                Some(i) => path[..i].to_string(),
            };
            continue;
        }
        let newpath = if path == "/" { format!("/{name}") } else { format!("{path}/{name}") };
        let is_link = matches!(fs::symlink_metadata(&newpath), Ok(m) if m.file_type().is_symlink());
        if !is_link {
            path = newpath;
            continue;
        }
        if let Some(cached) = seen.get(&newpath) {
            match cached {
                Some(resolved) => path = resolved.clone(),
                None => path = newpath, // a loop
            }
            continue;
        }
        let target = match fs::read_link(&newpath) {
            Ok(t) => utf8(t.into_os_string(), &newpath)?,
            Err(_) => {
                path = newpath;
                continue;
            }
        };
        if target.starts_with('/') {
            path = "/".to_string();
        }
        seen.insert(newpath.clone(), None);
        rest.push(Some(newpath));
        rest.push(None);
        let parts: Vec<&str> = target.split('/').collect();
        part_count += parts.len();
        rest.extend(parts.into_iter().rev().map(|s| Some(s.to_string())));
    }
    Ok(path)
}

fn utf8(s: std::ffi::OsString, what: &str) -> Result<String> {
    s.into_string().map_err(|raw| Error::Invalid(format!("{what} is not UTF-8: {raw:?}")))
}

fn path_str(p: &Path) -> Result<String> {
    p.to_str().map(str::to_string).ok_or_else(|| Error::Invalid(format!("a path is not UTF-8: {p:?}")))
}

fn env_str(key: &str) -> Result<Option<String>> {
    match std::env::var_os(key) {
        None => Ok(None),
        Some(v) => utf8(v, key).map(Some),
    }
}

// --- File checks ---

fn absent(e: &io::Error) -> bool {
    matches!(e.kind(), io::ErrorKind::NotFound | io::ErrorKind::NotADirectory)
}

/// `_exists`: only "not there" is false; any other failure is an error.
fn exists(p: &str) -> Result<bool> {
    match fs::metadata(p) {
        Ok(_) => Ok(true),
        Err(e) if absent(&e) => Ok(false),
        Err(e) => Err(io_err(p, e)),
    }
}

/// `_lstat`: None only when the path is not there.
fn lstat(p: &str) -> Result<Option<Metadata>> {
    match fs::symlink_metadata(p) {
        Ok(m) => Ok(Some(m)),
        Err(e) if absent(&e) => Ok(None),
        Err(e) => Err(io_err(p, e)),
    }
}

/// `os.path.isdir` / `os.path.islink` / `os.path.exists`: never an error.
fn isdir(p: &str) -> bool {
    fs::metadata(p).map(|m| m.is_dir()).unwrap_or(false)
}
fn islink(p: &str) -> bool {
    fs::symlink_metadata(p).map(|m| m.file_type().is_symlink()).unwrap_or(false)
}
fn py_exists(p: &str) -> bool {
    fs::metadata(p).is_ok()
}

fn samefile(a: &str, b: &str) -> bool {
    match (fs::metadata(a), fs::metadata(b)) {
        (Ok(x), Ok(y)) => x.dev() == y.dev() && x.ino() == y.ino(),
        _ => false,
    }
}

/// `_same`: one folder, equal once normalized or the same file by identity.
fn same(a: &str, b: &str) -> bool {
    normpath(a) == normpath(b) || samefile(a, b)
}

/// `os.access(p, os.X_OK)` for a folder: whether a name inside it can be looked up.
fn searchable(p: &str) -> bool {
    fs::symlink_metadata(format!("{p}/.")).is_ok()
}

// --- Roots ---

/// `_home`: $HOME when set and non-empty, else the account's home; never relative.
fn home() -> Result<String> {
    let value = env_str("HOME")?;
    let home = match value.as_deref() {
        Some(v) if !v.is_empty() => pl(v),
        _ => {
            // HOME is unset or empty, so home_dir() reads the password database.
            let dir = std::env::home_dir().ok_or_else(|| {
                Error::Invalid("HOME is empty and this account has no home in the password database".into())
            })?;
            pl(&path_str(&dir)?)
        }
    };
    if !home.starts_with('/') {
        return Err(Error::Invalid(format!("HOME must be an absolute path: {value:?}")));
    }
    Ok(norm(&home))
}

/// `_expand`: a leading ~ or ~/ is the home; ~user is refused.
fn expand(value: &str) -> Result<String> {
    if value == "~" {
        return home();
    }
    if let Some(rest) = value.strip_prefix("~/") {
        return Ok(join(&home()?, rest));
    }
    if value.starts_with('~') {
        return Err(Error::Invalid(format!("~user paths are not supported: {value:?}")));
    }
    Ok(pl(value))
}

fn absolute(key: &str, value: &str) -> Result<String> {
    let path = expand(value)?;
    if !path.starts_with('/') {
        return Err(Error::Invalid(format!("{key} must be an absolute path (or start with ~/): {value:?}")));
    }
    Ok(norm(&path))
}

pub fn machine_root() -> Result<PathBuf> {
    machine_root_str().map(PathBuf::from)
}

fn machine_root_str() -> Result<String> {
    match env_str(MACHINE_ENV)? {
        Some(v) if !v.is_empty() => absolute(MACHINE_ENV, &v),
        _ => expand(MACHINE_DEFAULT),
    }
}

pub fn workspace_root() -> Result<PathBuf> {
    workspace_root_str().map(PathBuf::from)
}

fn workspace_root_str() -> Result<String> {
    let mut root = None;
    for key in WORKSPACE_ENV {
        if let Some(v) = env_str(key)?
            && !v.is_empty()
        {
            root = Some(absolute(key, &v)?);
            break;
        }
    }
    let root = match root {
        Some(r) => r,
        None => expand(WORKSPACE_DEFAULT)?,
    };
    if same(&root, &home()?) {
        return Err(Error::Invalid(format!(
            "the workspace root cannot be $HOME: {root} (workspace.* would land in the machine root)"
        )));
    }
    Ok(root)
}

// --- git ---

enum GitError {
    /// git could not run, or ran past GIT_TIMEOUT (Python: OSError, SubprocessError).
    Run(String),
    /// A NUL byte in an argument, or output that is not UTF-8 (Python: ValueError).
    Invalid,
}

struct GitOut {
    code: Option<i32>,
    stdout: String,
    stderr: String,
}

/// Strict UTF-8, no newline translation (a folder name may hold a `\r`).
fn text(bytes: Vec<u8>) -> std::result::Result<String, GitError> {
    String::from_utf8(bytes).map_err(|_| GitError::Invalid)
}

/// `_git`: git with GIT_DIR and GIT_WORK_TREE removed, bounded by GIT_TIMEOUT.
fn git(args: &[&str]) -> std::result::Result<GitOut, GitError> {
    if args.iter().any(|a| a.contains('\0')) {
        return Err(GitError::Invalid);
    }
    let mut child = Command::new("git")
        .args(args)
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .process_group(0)
        .spawn()
        .map_err(|e| GitError::Run(e.to_string()))?;
    // The deadline covers the pipes too, as Python's communicate(timeout) does: a
    // process git leaves behind can hold them open after git itself exits. A timeout
    // kills git's whole process group, so the reader threads below reach EOF and end.
    // git is reaped only after both pipes close, so its pid (the group's id) is still
    // reserved whenever the group is signalled: the kill cannot reach a reused pid.
    let deadline = Instant::now() + GIT_TIMEOUT;
    let give_up = |child: &mut Child| {
        let quiet = || Stdio::null();
        let _ = Command::new("/bin/sh")
            .args(["-c", "kill -s KILL -- \"-$1\"", "sh", &child.id().to_string()])
            .stdin(quiet())
            .stdout(quiet())
            .stderr(quiet())
            .status();
        let _ = child.kill();
        let _ = child.wait();
        GitError::Run(format!("git timed out after {} s", GIT_TIMEOUT.as_secs()))
    };
    let (out_tx, out_rx) = mpsc::channel();
    let (err_tx, err_rx) = mpsc::channel();
    for (mut pipe, tx) in [
        (Box::new(child.stdout.take().expect("piped")) as Box<dyn Read + Send>, out_tx),
        (Box::new(child.stderr.take().expect("piped")), err_tx),
    ] {
        std::thread::spawn(move || {
            let mut v = Vec::new();
            let _ = pipe.read_to_end(&mut v);
            let _ = tx.send(v);
        });
    }
    let left = || deadline.saturating_duration_since(Instant::now());
    let stdout = out_rx.recv_timeout(left()).map_err(|_| give_up(&mut child))?;
    let stderr = err_rx.recv_timeout(left()).map_err(|_| give_up(&mut child))?;
    let status = loop {
        match child.try_wait() {
            Ok(Some(s)) => break s,
            Ok(None) if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(5)),
            Ok(None) => return Err(give_up(&mut child)),
            Err(e) => return Err(GitError::Run(e.to_string())),
        }
    };
    Ok(GitOut { code: status.code(), stdout: text(stdout)?, stderr: text(stderr)? })
}

/// A git failure inside a tree read: TreeReadError, except a decode failure (ValueError).
fn tree_git(root: &str, args: &[&str]) -> Result<GitOut> {
    git(args).map_err(|e| match e {
        GitError::Run(m) => Error::TreeRead(format!("git could not run in {root}: {m}")),
        GitError::Invalid => Error::Invalid(format!("a NUL in git's arguments, or its output in {root} is not UTF-8")),
    })
}

// --- Repo scope ---

fn scoped<'a>(name: &'a str, scopes: &[&str]) -> &'a str {
    for scope in scopes {
        if let Some(rest) = name.strip_prefix(scope).and_then(|r| r.strip_prefix('.')) {
            return rest;
        }
    }
    name
}

fn repo_entry(name: &str) -> Result<(&'static str, bool, bool)> {
    let key = scoped(name, &["repo", "workspace"]);
    REPO.iter()
        .find(|(n, ..)| *n == key)
        .map(|&(_, p, legacy, owner)| (p, legacy, owner))
        .ok_or_else(|| Error::UnknownName(name.to_string()))
}

fn state_entry(name: &str) -> Option<&'static str> {
    let key = scoped(name, &["repo", "workspace"]);
    REPO_STATE.iter().find(|(n, _)| *n == key).map(|&(_, p)| p)
}

fn machine_entry(name: &str) -> Result<(&'static str, Option<&'static str>)> {
    let key = scoped(name, &["machine"]);
    MACHINE
        .iter()
        .find(|(n, ..)| *n == key)
        .map(|&(_, p, legacy)| (p, legacy))
        .ok_or_else(|| Error::UnknownName(name.to_string()))
}

/// `_require_root`: a non-empty root without a `..` part.
fn require_root(root: &Path) -> Result<String> {
    let s = path_str(root)?;
    // Every reader that takes a root passes it to lstat or git, which refuse a NUL
    // byte in Python (ValueError); refusing it here gives that answer up front.
    if s.contains('\0') {
        return Err(Error::Invalid(format!("a repo root holds a NUL byte: {s:?}")));
    }
    if s.is_empty() {
        return Err(Error::Invalid("a repo root is required (an empty one would mean the cwd)".into()));
    }
    let p = pl(&s);
    if p.split('/').any(|c| c == "..") {
        return Err(Error::Invalid(format!("a repo root has no `..` part (a git top level never does): {s}")));
    }
    Ok(p)
}

/// A repo's name in machine state: its top-level folder name plus the first 12 hex
/// digits of the sha256 of its real path. `_root` stands in for the name of `/`.
pub fn repo_key(root: &Path) -> Result<String> {
    let root = require_root(root)?;
    let mut probe = abspath(&root)?;
    while !py_exists(&probe) && probe != parent(&probe) {
        if islink(&probe) {
            return Err(Error::Invalid(format!("{probe} is a dangling symlink above the repo root {root}")));
        }
        probe = parent(&probe);
    }
    let real = realpath(&root)?;
    let name = match real.rsplit('/').next() {
        Some(n) if !n.is_empty() => n,
        _ => "_root",
    };
    Ok(format!("{name}-{}", &sha256_hex(real.as_bytes())[..12]))
}

/// Where a repo's runtime state lives once moved: $BROOMVA_HOME/state/repos/<repo_key>.
pub fn state_dir(root: &Path) -> Result<PathBuf> {
    state_dir_str(root).map(PathBuf::from)
}

fn state_dir_str(root: &Path) -> Result<String> {
    let machine = machine_root_str()?;
    Ok(join(&join(&join(&machine, "state"), "repos"), &repo_key(root)?))
}

/// `_contained`: .broomva/ and .control/ are absent or real, searchable folders.
fn contained(root: &str) -> Result<()> {
    for folder in [REPO_DIR, REPO_LEGACY_DIR] {
        let p = join(root, folder);
        let Some(info) = lstat(&p)? else { continue };
        if info.file_type().is_symlink() {
            return Err(Error::Layout(format!("{p} is a symlink; it must be a real folder in the repo")));
        }
        if !info.is_dir() {
            return Err(Error::Layout(format!("{p} is not a folder")));
        }
        if !searchable(&p) {
            return Err(Error::Io(
                p.clone(),
                io::Error::new(io::ErrorKind::PermissionDenied, format!("{p} cannot be searched")),
            ));
        }
    }
    Ok(())
}

/// `_entry`: the path if it is absent, or a real file or folder (and, for an
/// owner-written file, a single link).
fn entry(p: String, owner: bool) -> Result<String> {
    let Some(info) = lstat(&p)? else { return Ok(p) };
    let kind = info.file_type();
    if kind.is_symlink() {
        return Err(Error::Layout(format!("{p} is a symlink; a registry entry is a real file or folder")));
    }
    if !(kind.is_file() || kind.is_dir()) {
        return Err(Error::Layout(format!("{p} is neither a file nor a folder")));
    }
    if owner && kind.is_file() && info.nlink() > 1 {
        return Err(Error::Layout(format!("{p} has {} links; an owner-written file has one", info.nlink())));
    }
    Ok(p)
}

/// `_toplevel`: the git top level of `target`, from its nearest real ancestor folder.
fn toplevel(target: &str) -> Result<Option<String>> {
    let mut dir = if isdir(target) && !islink(target) { target.to_string() } else { parent(target) };
    while (islink(&dir) || !isdir(&dir)) && dir != parent(&dir) {
        dir = parent(&dir);
    }
    let out = match git(&["-C", &dir, "rev-parse", "--show-toplevel"]) {
        Ok(o) => o,
        Err(GitError::Run(m)) => return Err(Error::TreeRead(format!("git could not run: {m}"))),
        Err(GitError::Invalid) => {
            return Err(Error::Invalid("a NUL in git's arguments, or its output is not UTF-8".into()));
        }
    };
    // Only git's newline is dropped: a folder name may end in a space.
    let printed = out.stdout.strip_suffix('\n').unwrap_or(&out.stdout);
    if out.code != Some(0) || printed.is_empty() {
        return Ok(None);
    }
    let top = pl(printed);
    if samefile(&top, &home()?) {
        return Ok(None); // a git repo at $HOME would make the repo and machine scopes coincide
    }
    Ok(Some(top))
}

/// The repo a tool operates on: the git top level of `target`, else of
/// $CLAUDE_PROJECT_DIR, else None. Never the cwd: an empty target is no target.
pub fn repo_root(target: Option<&Path>) -> Result<Option<PathBuf>> {
    if let Some(t) = target {
        let t = path_str(t)?;
        if !t.is_empty() {
            return Ok(toplevel(&pl(&t))?.map(PathBuf::from));
        }
    }
    match env_str("CLAUDE_PROJECT_DIR")? {
        Some(p) if !p.is_empty() => Ok(toplevel(&pl(&p))?.map(PathBuf::from)),
        _ => Ok(None),
    }
}

/// The repo-relative paths a name may hold, new first.
pub fn repo_rels(name: &str) -> Result<Vec<String>> {
    if let Some(state) = state_entry(name) {
        return Ok(vec![format!("{REPO_LEGACY_DIR}/{state}")]);
    }
    let (path, legacy, _) = repo_entry(name)?;
    let new = format!("{REPO_DIR}/{path}");
    Ok(if legacy { vec![new, format!("{REPO_LEGACY_DIR}/{path}")] } else { vec![new] })
}

/// Whether the repo at `root` has moved: any name with a legacy location is under .broomva/.
pub fn moved(root: &Path) -> Result<bool> {
    let root = require_root(root)?;
    moved_str(&root)
}

fn moved_str(root: &str) -> Result<bool> {
    contained(root)?;
    let mut found = Vec::new();
    for &(_, path, legacy, owner) in REPO {
        if legacy {
            let p = join(&join(root, REPO_DIR), path);
            if lstat(&p)?.is_some() {
                found.push((p, owner));
            }
        }
    }
    let any = !found.is_empty();
    for (p, owner) in found {
        entry(p, owner)?;
    }
    Ok(any)
}

/// Names still under .control/ in a repo that has moved.
pub fn partially_moved(root: &Path) -> Result<Vec<String>> {
    let root = require_root(root)?;
    if !moved_str(&root)? {
        return Ok(Vec::new());
    }
    let mut names = Vec::new();
    for &(name, path, legacy, _) in REPO {
        if legacy && exists(&join(&join(&root, REPO_LEGACY_DIR), path))? {
            names.push(name.to_string());
        }
    }
    Ok(names)
}

/// Where `name` lives on disk in the repo at `root` (the migration rule).
pub fn repo_path(name: &str, root: &Path) -> Result<PathBuf> {
    repo_path_str(name, root).map(PathBuf::from)
}

fn repo_path_str(name: &str, root: &Path) -> Result<String> {
    if let Some(state) = state_entry(name) {
        let root = require_root(root)?;
        contained(&root)?;
        let new = join(&state_dir_str(Path::new(&root))?, state);
        let old = join(&join(&root, REPO_LEGACY_DIR), state);
        if exists(&new)? || lstat(&new)?.is_some() {
            return entry(new, false);
        }
        if exists(&old)? || lstat(&old)?.is_some() || (isdir(&join(&root, REPO_LEGACY_DIR)) && !moved_str(&root)?) {
            return entry(old, false);
        }
        return entry(new, false);
    }
    let (path, legacy, owner) = repo_entry(name)?;
    let root = require_root(root)?;
    contained(&root)?;
    let new = join(&join(&root, REPO_DIR), path);
    let old = join(&join(&root, REPO_LEGACY_DIR), path);
    if !legacy || exists(&new)? || lstat(&new)?.is_some() {
        return entry(new, owner);
    }
    if exists(&old)? || lstat(&old)?.is_some() || (isdir(&join(&root, REPO_LEGACY_DIR)) && !moved_str(&root)?) {
        return entry(old, owner);
    }
    entry(new, owner)
}

pub fn workspace_path(name: &str) -> Result<PathBuf> {
    let root = workspace_root_str()?;
    repo_path(name, Path::new(&root))
}

pub fn machine_path(name: &str) -> Result<PathBuf> {
    let (path, legacy) = machine_entry(name)?;
    let new = join(&machine_root_str()?, path);
    let Some(legacy) = legacy else { return Ok(PathBuf::from(new)) };
    if exists(&new)? {
        return Ok(PathBuf::from(new));
    }
    let old = expand(legacy)?;
    Ok(PathBuf::from(if exists(&old)? { old } else { new }))
}

fn check_rev(rev: &str) -> Result<()> {
    if rev.is_empty() || rev.starts_with('-') || rev.contains('\0') {
        return Err(Error::Invalid(format!("not a revision: {rev:?}")));
    }
    Ok(())
}

fn verify_rev(root: &str, rev: &str) -> Result<()> {
    let ok = tree_git(root, &["-C", root, "rev-parse", "--verify", "--quiet", &format!("{rev}^{{tree}}")])?;
    if ok.code != Some(0) {
        return Err(Error::TreeRead(format!("cannot read revision {rev:?} in {root}")));
    }
    Ok(())
}

/// The repo-relative path `name` has in git tree `rev` of the repo at `root`, new
/// before legacy; None when the tree holds neither.
pub fn tree_path(name: &str, root: &Path, rev: &str) -> Result<Option<String>> {
    let rels = repo_rels(name)?;
    let root = require_root(root)?;
    check_rev(rev)?;
    verify_rev(&root, rev)?;
    tree_contained(&root, rev)?;
    for rel in &rels {
        let out = tree_git(&root, &["-C", &root, "ls-tree", "--full-tree", "-z", rev, "--", rel])?;
        if out.code != Some(0) {
            return Err(Error::TreeRead(format!("git ls-tree failed in {root}: {}", out.stderr.trim())));
        }
        for line in out.stdout.split('\0') {
            let (meta, entry) = line.split_once('\t').unwrap_or((line, ""));
            if entry == rel {
                let mode = meta.split(' ').next().unwrap_or("");
                if !["040000", "100644", "100755"].contains(&mode) {
                    return Err(Error::Layout(format!("{rel} is not a folder or a file in {rev} (mode {mode})")));
                }
                return Ok(Some(rel.clone()));
            }
        }
    }
    Ok(None)
}

/// `_tree_contained`: .broomva and .control in tree `rev` are folders.
fn tree_contained(root: &str, rev: &str) -> Result<()> {
    let out = tree_git(root, &["-C", root, "ls-tree", "--full-tree", "-z", rev, "--", REPO_DIR, REPO_LEGACY_DIR])?;
    if out.code != Some(0) {
        return Err(Error::TreeRead(format!("git ls-tree failed in {root}: {}", out.stderr.trim())));
    }
    for line in out.stdout.split('\0') {
        let (meta, entry) = line.split_once('\t').unwrap_or((line, ""));
        if (entry == REPO_DIR || entry == REPO_LEGACY_DIR) && !meta.starts_with("040000 ") {
            let mode = meta.split(' ').next().unwrap_or("");
            return Err(Error::Layout(format!("{entry} is not a folder in {rev} ({mode})")));
        }
    }
    Ok(())
}

fn tree_entries(root: &str, rev: &str, folder: &str) -> Result<HashSet<String>> {
    let spec = format!("{folder}/");
    let out = tree_git(root, &["-C", root, "ls-tree", "--full-tree", "--name-only", "-z", rev, "--", &spec])?;
    if out.code != Some(0) {
        return Err(Error::TreeRead(format!("git ls-tree failed in {root}: {}", out.stderr.trim())));
    }
    Ok(out.stdout.split('\0').filter_map(|e| e.strip_prefix(&spec)).map(str::to_string).collect())
}

/// Names present under both roots, on disk or in git tree `rev`.
pub fn shadowed(root: &Path, rev: Option<&str>) -> Result<Vec<String>> {
    let root = require_root(root)?;
    if let Some(rev) = rev {
        check_rev(rev)?;
        verify_rev(&root, rev)?;
        tree_contained(&root, rev)?;
        let new = tree_entries(&root, rev, REPO_DIR)?;
        let old = tree_entries(&root, rev, REPO_LEGACY_DIR)?;
        return Ok(REPO
            .iter()
            .filter(|(_, path, legacy, _)| *legacy && new.contains(*path) && old.contains(*path))
            .map(|(name, ..)| name.to_string())
            .collect());
    }
    contained(&root)?;
    let (new_root, old_root) = (join(&root, REPO_DIR), join(&root, REPO_LEGACY_DIR));
    let mut names = Vec::new();
    for &(name, path, legacy, _) in REPO {
        if legacy && exists(&join(&new_root, path))? && exists(&join(&old_root, path))? {
            names.push(name.to_string());
        }
    }
    let state = state_dir_str(Path::new(&root))?;
    for &(name, path) in REPO_STATE {
        if exists(&join(&state, path))? && exists(&join(&old_root, path))? {
            names.push(name.to_string());
        }
    }
    Ok(names)
}

/// Resolve a scoped name: `repo.X` (needs `root`), `workspace.X` or `machine.X`.
pub fn resolve(name: &str, root: Option<&Path>) -> Result<PathBuf> {
    if name.starts_with("machine.") {
        return machine_path(name);
    }
    if name.starts_with("workspace.") {
        return workspace_path(name);
    }
    if name.starts_with("repo.") {
        let Some(root) = root else { return Err(Error::Invalid("a repo name needs a root".into())) };
        return repo_path(name, root);
    }
    Err(Error::UnknownName(name.to_string()))
}

pub fn all_names() -> Vec<String> {
    let repo: Vec<&str> = REPO.iter().map(|r| r.0).chain(REPO_STATE.iter().map(|r| r.0)).collect();
    let mut out: Vec<String> = repo.iter().map(|n| format!("repo.{n}")).collect();
    out.extend(repo.iter().map(|n| format!("workspace.{n}")));
    out.extend(MACHINE.iter().map(|m| format!("machine.{}", m.0)));
    out
}

// --- sha256 (FIPS 180-4), for repo_key ---

const K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98,
    0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8,
    0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
    0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
    0xc67178f2,
];

pub(crate) fn sha256_hex(data: &[u8]) -> String {
    let mut h: [u32; 8] =
        [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&((data.len() as u64) * 8).to_be_bytes());
    for block in msg.chunks(64) {
        let mut w = [0u32; 64];
        for (i, word) in block.chunks(4).enumerate() {
            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let t1 = hh.wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        for (x, y) in h.iter_mut().zip([a, b, c, d, e, f, g, hh]) {
            *x = x.wrapping_add(y);
        }
    }
    h.iter().map(|x| format!("{x:08x}")).collect()
}
